from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Optional, List
from mercury_ocip.commands.base_command import OCIType, OCICommand, OCIRequest, OCIDataResponse, Nillable, OCINil

@dataclass
class AuthenticationRequest(OCIRequest):
    """
    `AuthenticationRequest()`/AuthenticationResponse is 1st stage of the 2 stage OCI login process.


    Attributes:
        user_id (str):
    """
    user_id: str = field(default_factory=str, metadata={'alias': 'userId'})

class AuthenticationResponse(OCIDataResponse):
    """
    `AuthenticationRequest()`/Response is 1st stage of the 2 stage OCI login process.


    Attributes:
        user_id (str): userId
        nonce (str): nonce
        password_algorithm (str): passwordAlgorithm
    """
    user_id: str = field(default_factory=str, metadata={'alias': 'userId'})
    nonce: str = field(default_factory=str, metadata={'alias': 'nonce'})
    password_algorithm: str = field(default_factory=str, metadata={'alias': 'passwordAlgorithm'})

class LoginRequest14sp4(OCIRequest):
    """
    `LoginRequest14sp4()`/LoginResponse14sp4 is 2nd stage of the 2 stage OCI login process.

    The signedPassword is not required for external authentication login from a trusted
    host (ACL).

    Attributes:
        user_id (str): userId
        signed_password (str): signedPassword *Optional*
        plain_text_password (str): plainTextPassword *Optional*
    """
    user_id: str = field(default_factory=str, metadata={'alias': 'userId'})
    signed_password: Optional[str] = field(default=None, metadata={'alias': 'signedPassword'})
    plain_text_password: Optional[str] = field(default=None, metadata={'alias': 'plainTextPassword'})

class LoginResponse14sp4(OCIDataResponse):
    """
    `LoginRequest14sp4()`/Response14sp4 is 2nd stage of the 2 stage OCI login process.


    Attributes:
        login_type (str): loginType
        locale (str): locale
        encoding (str): encoding
        group_id (str): groupId *Optional*
        service_provider_id (str): serviceProviderId *Optional*
        is_enterprise (bool): isEnterprise
        password_expires_days (int): passwordExpiresDays *Optional*
        user_domain (str): userDomain
    """
    login_type: str = field(default_factory=str, metadata={'alias': 'loginType'})
    locale: str = field(default_factory=str, metadata={'alias': 'locale'})
    encoding: str = field(default_factory=str, metadata={'alias': 'encoding'})
    group_id: Optional[str] = field(default=None, metadata={'alias': 'groupId'})
    service_provider_id: Optional[str] = field(default=None, metadata={'alias': 'serviceProviderId'})
    is_enterprise: bool = field(default_factory=bool, metadata={'alias': 'isEnterprise'})
    password_expires_days: Optional[int] = field(default=None, metadata={'alias': 'passwordExpiresDays'})
    user_domain: str = field(default_factory=str, metadata={'alias': 'userDomain'})

