    audio_file_url: Optional[str] = field(default=None, metadata={'alias': 'audioFileUrl'})
    video_selection: str = field(metadata={'alias': 'videoSelection'})
    video_file: Optional[AnnouncementFileLevelKey] = field(default=None, metadata={'alias': 'videoFile'})
